class CardBuilder {
  final String title;
  final String subtitle;
  final String emoji;

  CardBuilder(this.title, this.subtitle, {String? emoji})
      : emoji = emoji ?? '📄';

  String describe() {
    return '[$emoji] $title - $subtitle';
  }

  Map<String, dynamic> toMap() {
    return {'title': title, 'subtitle': subtitle, 'emoji': emoji};
  }

  bool isLongTitle() {
    return title.length > 20;
  }
}

void main() {
  final card = CardBuilder('Hello World', 'A greeting card');
  print(card.describe());
  print(card.toMap());
  print('Long title: ${card.isLongTitle()}');

  final long = CardBuilder(
      'Một tiêu đề rất dài vượt quá hai mươi ký tự', 'Long', emoji: '🎯');
  print(long.describe());
  print('Long title: ${long.isLongTitle()}');
}

class ListFormatter {
  final List<Map<String, dynamic>> items;

  ListFormatter(this.items);

  List<Map<String, dynamic>> filterByCategory(String category) {
    return items.where((item) => item['category'] == category).toList();
  }

  List<String> toDisplayList() {
    return items.asMap().entries.map((entry) {
      return '[${entry.key}] ${entry.value['name']}: '
          '${entry.value['description']}';
    }).toList();
  }

  String summary() {
    final categories = items
        .map((item) => item['category'].toString())
        .toSet()
        .toList()
      ..sort();
    return 'Items: ${items.length}, Categories: [${categories.join(', ')}]';
  }
}

void main() {
  final items = [
    {'name': 'Apple', 'description': 'Red fruit', 'category': 'fruit'},
    {'name': 'Carrot', 'description': 'Orange veggie', 'category': 'vegetable'},
    {'name': 'Banana', 'description': 'Yellow fruit', 'category': 'fruit'},
  ];

  final formatter = ListFormatter(items);
  print('Fruit count: ${formatter.filterByCategory("fruit").length}');
  print(formatter.toDisplayList());
  print(formatter.summary());
}

class Badge {
  final int count;
  final String label;

  Badge(this.count, {this.label = ''});

  String get display {
    if (count >= 100) return '99+';
    return count.toString();
  }

  bool get isVisible => count > 0;

  String get color {
    if (count == 0) return '#9CA3AF';
    if (count <= 10) return '#EF4444';
    if (count <= 50) return '#F59E0B';
    return '#10B981';
  }

  String describe() => 'Badge($display, $label, $color)';
}

void main() {
  final msgs = Badge(5, label: 'msgs');
  final tasks = Badge(150, label: 'tasks');
  final empty = Badge(0);

  print(msgs.describe());
  print('Visible: ${msgs.isVisible}');
  print('Big badge: ${tasks.display}');
  print('Empty: ${empty.describe()}');
}

