class ListFormatter {
  final List<Map<String, dynamic>> items;

  ListFormatter(this.items);

  List<Map<String, dynamic>> filterByCategory(String category) {
    return items.where((item) => item['category'] == category).toList();
  }

  List<Map<String, dynamic>> sortByField(String field) {
    final sorted = List<Map<String, dynamic>>.from(items);
    sorted.sort((a, b) {
      final aVal = a[field]?.toString() ?? '';
      final bVal = b[field]?.toString() ?? '';
      return aVal.compareTo(bVal);
    });
    return sorted;
  }

  List<String> toDisplayList() {
    return items.asMap().entries.map((entry) {
      final index = entry.key;
      final item = entry.value;
      return '[$index] ${item['name']}: ${item['description']}';
    }).toList();
  }

  String summary() {
    final categories = items.map((item) => item['category'].toString()).toSet().toList()..sort();
    return 'Items: ${items.length}, Categories: [${categories.join(', ')}]';
  }

  List<Map<String, dynamic>> findByKeyword(String keyword) {
    final lower = keyword.toLowerCase();
    return items.where((item) {
      final name = item['name']?.toString().toLowerCase() ?? '';
      return name.contains(lower);
    }).toList();
  }
}

void main() {
  final items = [
    {'name': 'Apple', 'description': 'Red fruit', 'category': 'fruit'},
    {'name': 'Carrot', 'description': 'Orange veggie', 'category': 'vegetable'},
    {'name': 'Banana', 'description': 'Yellow fruit', 'category': 'fruit'},
  ];

  final formatter = ListFormatter(items);
  print('Fruit count: ${formatter.filterByCategory("fruit").length}');
  print(formatter.toDisplayList());
  print(formatter.summary());
  print('Find "an": ${formatter.findByKeyword("an")}');
