class LayoutStrategy {
  final double mobileBreakpoint;
  final double tabletBreakpoint;

  LayoutStrategy({
    this.mobileBreakpoint = 600,
    this.tabletBreakpoint = 1200,
  });

  String getLayout(double width) {
    if (width < mobileBreakpoint) return 'mobile';
    if (width < tabletBreakpoint) return 'tablet';
    return 'desktop';
  }

  int getColumns(double width) {
    final layout = getLayout(width);
    if (layout == 'mobile') return 1;
    if (layout == 'tablet') return 2;
    return 4;
  }

  double getPadding(double width) {
    final layout = getLayout(width);
    if (layout == 'mobile') return 8.0;
    if (layout == 'tablet') return 16.0;
    return 24.0;
  }

  double getFontSize(double width, String level) {
    final layout = getLayout(width);
    final sizes = {
      'title': {'mobile': 18.0, 'tablet': 24.0, 'desktop': 32.0},
      'body': {'mobile': 14.0, 'tablet': 16.0, 'desktop': 18.0},
      'caption': {'mobile': 10.0, 'tablet': 12.0, 'desktop': 14.0},
    };
    return sizes[level]?[layout] ?? 14.0;
  }

  String describe() {
    return 'Strategy(mobile<$mobileBreakpoint, tablet<$tabletBreakpoint, desktop)';
  }
}

void main() {
  final strategy = LayoutStrategy();
  print('400px: ${strategy.getLayout(400)}, cols=${strategy.getColumns(400)}, pad=${strategy.getPadding(400)}');
  print('800px: ${strategy.getLayout(800)}, cols=${strategy.getColumns(800)}, pad=${strategy.getPadding(800)}');
  print('1500px: ${strategy.getLayout(1500)}, cols=${strategy.getColumns(1500)}, pad=${strategy.getPadding(1500)}');
  print('Title@400: ${strategy.getFontSize(400, "title")}');
  print(strategy.describe());
}

