class DataTable {
  final List<String> columns;
  final List<List<String>> rows;

  DataTable(this.columns, this.rows);

  int get rowCount => rows.length;

  int get columnCount => columns.length;

  List<String> getColumn(int index) {
    return rows.map((row) => row[index]).toList();
  }

  List<List<String>> sortByColumn(int index, {bool ascending = true}) {
    final sorted = List<List<String>>.from(rows.map((r) => List<String>.from(r)));
    sorted.sort((a, b) {
      final cmp = a[index].compareTo(b[index]);
      return ascending ? cmp : -cmp;
    });
    return sorted;
  }

  List<List<String>> filter(String query) {
    final lower = query.toLowerCase();
    return rows.where((row) {
      return row.any((cell) => cell.toLowerCase().contains(lower));
    }).toList();
  }

  Map<String, String> getRow(int index) {
    final map = <String, String>{};
    for (int i = 0; i < columns.length; i++) {
      map[columns[i]] = rows[index][i];
    }
    return map;
  }

  String toFormatted({int cellPadding = 2}) {
    final pad = ' ' * cellPadding;
    final widths = List.generate(columns.length, (i) {
      final colWidth = columns[i].length;
      final dataWidth = rows.fold<int>(0, (max, row) {
        final len = row[i].length;
        return len > max ? len : max;
      });
      return colWidth > dataWidth ? colWidth : dataWidth;
    });

    String formatRow(List<String> cells) {
      return cells.asMap().entries.map((e) {
        return '${pad}${e.value.padRight(widths[e.key])}${pad}';
      }).join('|');
    }

    final sep = '+${widths.map((w) => '-' * (w + cellPadding * 2)).join('+')}+';
    final header = '|${formatRow(columns)}|';
    final dataRows = rows.map((r) => '|${formatRow(r)}|').join('\n$sep\n');

    return '$header\n$sep\n$dataRows';
  }

  String describe() {
    return 'DataTable(${columns.length}x${rows.length}, columns=[${columns.join(', ')}])';
  }
}

void main() {
  final table = DataTable(
    ['Name', 'Age', 'City'],
    [
      ['Alice', '25', 'HCM'],
      ['Bob', '30', 'HN'],
      ['Charlie', '22', 'HCM'],
    ],
  );

  print(table.describe());
  print('Rows: ${table.rowCount}');
  print('Column 0: ${table.getColumn(0)}');
  print('Row 1: ${table.getRow(1)}');
  print('Filter HCM: ${table.filter("HCM")}');
  print(table.toFormatted());
}
